import math

primes = [2, 3, 5, 7]
max_mn = 10
valid_triples = []

def is_power(number, base):
    if number <= 0:
        return False
    if number == 1:
        return base == 1 # Not applicable here since base >= 2

    # Check if number is a power of base
    if number % base != 0:
        return False

    exponent = 0
    temp = number
    while temp > 0 and temp % base == 0:
        temp //= base
        exponent += 1

    return temp == 1, exponent

for p in primes:
    for m in range(1, max_mn + 1):
        for n in range(1, max_mn + 1):

            # Condition 1: m^2 + n = p^a, a >= 2
            X = m**2 + n
            is_power_X, exponent_X = is_power(X, p)

            if is_power_X and exponent_X >= 2:

                # Condition 2: m + n^2 = p^b, b >= 2
                Y = m + n**2
                is_power_Y, exponent_Y = is_power(Y, p)

                if is_power_Y and exponent_Y >= 2:
                    valid_triples.append((m, n, p))

print("Valid triples (m, n, p):")
for triple in valid_triples:
    print(triple)

print("Total number of triples found:", len(valid_triples))

